import React, { useState, useEffect } from 'react';
import { Routes, Route, useLocation, useNavigate } from 'react-router-dom';
import Sidebar from './Dashboard/Layout/Sidebar';
import TopBar from './Dashboard/Layout/TopBar';
import MobileMenu from './Dashboard/Layout/MobileMenu';
import DashboardHome from './Dashboard/Widgets/DashboardHome';
import UsersPage from './Dashboard/Widgets/UsersPage';
import ProductsPage from './Dashboard/Widgets/ProductsPage';
import OrdersPage from './Dashboard/Widgets/OrdersPage';
import AnalyticsPage from './Dashboard/Widgets/AnalyticsPage';
import MessagesPage from './Dashboard/Widgets/MessagesPage';
import SettingsPage from './Dashboard/Widgets/SettingsPage';

const Dashboard = ({ onLogout }) => {
  const [sidebarOpen, setSidebarOpen] = useState(window.innerWidth >= 1024);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  const location = useLocation();
  const navigate = useNavigate();

  const storedUser = typeof window !== 'undefined' ? localStorage.getItem('userData') : null;
  const parsedUser = storedUser ? JSON.parse(storedUser) : null;
  const role = parsedUser?.role || 'user';

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 1024;
      setIsMobile(mobile);
      if (!mobile) setMobileMenuOpen(false);
    };
    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogoutClick = () => {
    if (onLogout) onLogout();
    navigate('/login');
  };

  const toggleSidebar = () => {
    if (isMobile) setMobileMenuOpen(!mobileMenuOpen);
    else setSidebarOpen(!sidebarOpen);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-neutral-50 to-primary-50 dark:from-neutral-950 dark:to-primary-950">
      <Sidebar
        sidebarOpen={isMobile ? mobileMenuOpen : sidebarOpen}
        location={location}
        onLogout={handleLogoutClick}
        isMobile={isMobile}
        userRole={role}
      />

      <div className={`transition-all duration-300 ${isMobile ? '' : 'lg:pl-64'}`}>
        <TopBar
          mobileMenuOpen={mobileMenuOpen}
          setMobileMenuOpen={setMobileMenuOpen}
          currentPath={location.pathname}
          toggleSidebar={toggleSidebar}
        />

        <main className="p-4 md:p-6">
          <Routes>
            <Route path="/" element={<DashboardHome />} />
            {role === 'admin' && (
              <>
                <Route path="users" element={<UsersPage />} />
                <Route path="products" element={<ProductsPage />} />
                <Route path="orders" element={<OrdersPage />} />
                <Route path="analytics" element={<AnalyticsPage />} />
              </>
            )}
            <Route path="messages" element={<MessagesPage />} />
            <Route path="settings" element={<SettingsPage />} />
          </Routes>
        </main>
      </div>

      <MobileMenu
        mobileMenuOpen={mobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen}
      />
    </div>
  );
};

export default Dashboard;
